CREATE OR REPLACE FUNCTION public.intranet_members() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_master(auth.uid()) THEN RAISE EXCEPTION 'Somente Master gerencia acessos' USING ERRCODE='42501'; END IF; RETURN (SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]') FROM(SELECT p.user_id id,coalesce(p.responsible_name,'Sem nome') name,array(SELECT role::text FROM public.user_roles WHERE user_id=p.user_id) roles FROM public.profiles p ORDER BY p.responsible_name)t); END $$;
REVOKE ALL ON FUNCTION public.intranet_members() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.intranet_members() TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.intranet_assign_sector(p_user uuid,p_sector text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF NOT public.is_master(auth.uid()) OR p_user=auth.uid() THEN RAISE EXCEPTION 'Somente Master altera acessos de outras contas' USING ERRCODE='42501'; END IF;
IF p_sector NOT IN ('comercial','marketing','administracao','financeiro','desenvolvimento','nenhum') THEN RAISE EXCEPTION 'Setor inválido'; END IF;
PERFORM pg_advisory_xact_lock(hashtextextended('intranet-role:'||p_user::text,0)); IF EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=p_user AND role::text IN ('master','senior')) THEN RAISE EXCEPTION 'Preserve o acesso gerencial desta conta'; END IF;
IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE user_id=p_user) THEN RAISE EXCEPTION 'Conta não encontrada'; END IF;
DELETE FROM public.user_roles WHERE user_id=p_user AND role::text IN ('admin','comercial','marketing','administracao','financeiro','desenvolvimento'); IF p_sector<>'nenhum' THEN INSERT INTO public.user_roles(user_id,role) VALUES(p_user,p_sector::public.app_role) ON CONFLICT(user_id,role) DO NOTHING; END IF; END $$;
REVOKE ALL ON FUNCTION public.intranet_assign_sector(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.intranet_assign_sector(uuid,text) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.guard_submission_privileged_fields() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_can_approve boolean; v_is_admin boolean; v_sector boolean; BEGIN
v_is_admin:=public.is_admin_or_master(auth.uid()) OR (public.can_write_finance(auth.uid()) AND (NEW.highlight_grant_type='paid' OR OLD.highlight_grant_type='paid'));
v_sector:=public.intranet_can_access('administracao') AND current_setting('app.intranet_moderation',true)='yes';
SELECT EXISTS(SELECT 1 FROM public.collaborators c WHERE c.user_id=auth.uid() AND c.is_active AND c.can_approve) INTO v_can_approve;
IF NOT v_is_admin THEN NEW.is_highlight:=OLD.is_highlight; NEW.highlight_package_id:=OLD.highlight_package_id; NEW.highlight_starts_at:=OLD.highlight_starts_at; NEW.highlight_until:=OLD.highlight_until; NEW.highlight_hidden:=OLD.highlight_hidden; NEW.highlight_grant_type:=OLD.highlight_grant_type; NEW.published_at:=OLD.published_at; NEW.editorial_status:=OLD.editorial_status;
IF NOT v_sector THEN NEW.approved_by:=OLD.approved_by; NEW.approved_at:=OLD.approved_at; NEW.rejected_by:=OLD.rejected_by; NEW.rejected_at:=OLD.rejected_at; END IF;
IF NOT v_can_approve AND NOT v_sector THEN NEW.status:=OLD.status; NEW.moderation_status:=OLD.moderation_status; NEW.rejection_reason:=OLD.rejection_reason; NEW.admin_notes:=OLD.admin_notes; NEW.flyer_aprovado:=OLD.flyer_aprovado; NEW.flyer_approved_at:=OLD.flyer_approved_at; END IF; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.intranet_moderate(p_id uuid,p_approve boolean) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_status text; v_target text:=CASE WHEN p_approve THEN 'aprovado' ELSE 'rejeitado' END; BEGIN
IF NOT public.intranet_can_access('administracao') THEN RAISE EXCEPTION 'Sem acesso à curadoria' USING ERRCODE='42501'; END IF;
IF p_approve AND EXISTS(SELECT 1 FROM public.submissions WHERE id=p_id AND promotion_choice='highlight' AND highlight_grant_type IS DISTINCT FROM 'courtesy') THEN RAISE EXCEPTION 'Patrocinado: registre a baixa no Financeiro antes de liberar'; END IF;
PERFORM set_config('app.intranet_moderation','yes',true);
UPDATE public.submissions SET status=v_target,approved_at=CASE WHEN p_approve THEN now() ELSE NULL END,approved_by=CASE WHEN p_approve THEN auth.uid() ELSE NULL END,rejected_at=CASE WHEN NOT p_approve THEN now() ELSE NULL END,rejected_by=CASE WHEN NOT p_approve THEN auth.uid() ELSE NULL END WHERE id=p_id AND status='pendente' AND deleted_at IS NULL RETURNING status INTO v_status;
IF v_status IS DISTINCT FROM v_target THEN RAISE EXCEPTION 'O evento já foi revisado ou a alteração não foi autorizada'; END IF; RETURN jsonb_build_object('success',true); END $$;
REVOKE ALL ON FUNCTION public.intranet_moderate(uuid,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.intranet_moderate(uuid,boolean) TO authenticated,service_role;